def decode_genome(n, s):
    # Count the number of each nucleotide in the input string
    counts = {'A': 0, 'C': 0, 'G': 0, 'T': 0}
    question_marks = s.count('?')

    for nucleotide in s:
        if nucleotide in counts:
            counts[nucleotide] += 1

    # Calculate the target count for each nucleotide
    target_count = n // 4

    # Check if it's possible to decode the genome
    if any(counts[nucleotide] > target_count for nucleotide in counts):
        return "==="

    # Replace '?' with the appropriate nucleotides to balance the counts
    result = list(s)
    for i in range(n):
        if s[i] == '?':
            for nucleotide in counts:
                if counts[nucleotide] < target_count:
                    result[i] = nucleotide
                    counts[nucleotide] += 1
                    break

    return ''.join(result)

